export function detectSealedHost({ env = process.env, execPath = process.execPath, argv = process.argv, profileName } = {}) {
  const home = String(env?.DSH_HOME ?? '').toLowerCase()
  if (home.includes('com.deepseek.dsh.desktop.aio')
    && /resources[\\/]+node[\\/]+node\.exe$/i.test(String(execPath ?? ''))
    && (Array.isArray(argv) ? argv : []).includes('web-desktop')) return FLAVOR_AIO
  // The Android app launches its own kernel and keeps its own authorization.
  // Require the native launch markers and matching private home, not a desktop
  // profile alias. Server-side GitHub/Star authorization remains mandatory.
  const files = String(env?.DSH_PHONE_FILES ?? '')
  if (profileName === 'phone' && env?.DSH_PHONE_ANDROID === '1'
    && /^\/data\/(?:user\/0|data)\/com\.dshphone\/files$/.test(files)
    && env?.DSH_HOME === `${files}/dsh-home`
    && /^\/data\/app\/(?:[^/]+\/)?com\.dshphone-[^/]+\/lib\/arm64\/libnode\.so$/.test(String(execPath ?? ''))) return FLAVOR_PHONE
  if (profileName === 'web' || profileName === 'web-desktop') return FLAVOR_WEB
  if (profileName === 'desktop') return FLAVOR_HARNESS
  return null
}

