function EacStatusPill({ auth, t }) {
  const text = auth === undefined ? t('loading')
    : auth.available !== true ? t('eac.pillUnavailable')
      : auth.unverified === true ? t('eac.pillUnverified')
        : auth.authorized === true ? t('eac.pillOk') : t('eac.pillLocked')
  return h(Pill, { strong: true, tone: auth?.available === true && auth.unverified !== true && auth.authorized === true ? 'ok' : 'warn' }, text)
}

