function sharedPushSource(url, options = {}) {
  const Source = options.EventSource ?? globalThis.EventSource
  const Channel = options.BroadcastChannel ?? globalThis.BroadcastChannel
  const locks = options.locks ?? globalThis.navigator?.locks
  const doc = options.document ?? globalThis.document
  const listeners = new Map()
  const controller = new AbortController()
  const channel = Channel && locks?.request ? new Channel('dsh-ofm-push-v1') : null
  let disposed = false
  let upstream
  let lastHello
  let release
  const names = ['announcements', 'update', 'upgraded', 'hello']
  const handle = {
    onopen: null,
    onerror: null,
    addEventListener(name, callback) {
      if (!listeners.has(name)) listeners.set(name, new Set())
      listeners.get(name).add(callback)
    },
    close() {
      if (disposed) return
      disposed = true
      upstream?.close()
      upstream = undefined
      controller.abort()
      release?.()
      doc?.removeEventListener('visibilitychange', visible)
      channel?.close()
      listeners.clear()
    },
  }
  const deliver = message => {
    if (disposed) return
    if (message?.type === 'open') handle.onopen?.()
    else if (message?.type === 'error') handle.onerror?.()
    else if (message?.type === 'event' && names.includes(message.name) && typeof message.data === 'string') {
      if (message.name === 'hello') lastHello = message.data
      for (const callback of listeners.get(message.name) ?? []) callback({ data: message.data })
    }
  }
  const publish = message => {
    deliver(message)
    if (!disposed) channel?.postMessage(message)
  }
  const open = () => {
    if (disposed || upstream !== undefined) return
    upstream = new Source(url)
    upstream.onopen = () => publish({ type: 'open' })
    upstream.onerror = () => publish({ type: 'error' })
    for (const name of names) upstream.addEventListener(name, event => publish({ type: 'event', name, data: event.data }))
  }
  const visible = () => {
    if (doc?.visibilityState === 'hidden') {
      upstream?.close()
      upstream = undefined
    } else open()
  }
  if (channel !== null) {
    channel.onmessage = event => {
      if (event.data?.type === 'hello-request') {
        if (upstream !== undefined && lastHello !== undefined) channel.postMessage({ type: 'event', name: 'hello', data: lastHello })
      } else deliver(event.data)
    }
    // Do not await the lease from apply(): follower tabs must finish booting.
    locks.request('dsh-ofm-push-v1', { signal: controller.signal }, async () => {
      if (disposed) return
      const held = new Promise(resolve => { release = resolve })
      open()
      await held
    }).catch(() => { if (!disposed) handle.onerror?.() })
    channel.postMessage({ type: 'hello-request' })
  } else {
    // Older browsers still release optional SSE connections in hidden tabs.
    doc?.addEventListener('visibilitychange', visible)
    visible()
  }
  return handle
}
